222: func taskPlanMemorySize(plan *taskplan.Plan) int64 {
223: 	size := int64(1 << 10)
224: 	for _, input := range plan.Inputs {
225: 		size += int64(len(input.Bytes))
226: 	}
227: 	return size
228: }
