20: func (db *DB) MigrateTaskPlanInputsBatch(ctx context.Context) error {
21: 	complete, err := db.taskPlanInputMigrationComplete(ctx)
22: 	if err != nil || complete {
23: 		return err
24: 	}
25: 	lock, err := awaitMigrationLock(ctx, db.Path)
26: 	if err != nil {
27: 		return err
28: 	}
29: 	defer lock.Close()
30: 
31: 	var taskDone, revisionDone int
32: 	var taskCursor, revisionTaskCursor int64
33: 	var revisionCursor int
34: 	if err := db.QueryRowContext(ctx, `SELECT tasks_done,revisions_done,task_cursor,revision_task_cursor,revision_cursor FROM task_plan_input_migration WHERE id=1`).Scan(&taskDone, &revisionDone, &taskCursor, &revisionTaskCursor, &revisionCursor); err != nil {
35: 		return err
36: 	}
37: 	if taskDone == 0 {
38: 		if err := db.migrateTaskPlanRowsBatch(ctx, taskCursor); err != nil {
39: 			return err
40: 		}
41: 	}
42: 	if revisionDone == 0 {
43: 		if err := db.migrateTaskPlanRevisionRowsBatch(ctx, revisionTaskCursor, revisionCursor); err != nil {
44: 			return err
45: 		}
46: 	}
