39: func (db *DB) bindTaskPlan(task Task, sequence int, workflowRunID string) (string, error) {
40: 	plan, err := task.AdmittedPlan()
41: 	if err != nil || plan == nil {
42: 		return "", err
43: 	}
44: 	if plan.Revision != 1 || plan.PreviousSHA256 != "" {
45: 		return "", fmt.Errorf("new Task requires execution plan revision 1")
46: 	}
47: 	if plan.Workflow != nil && plan.Workflow.RunID == "new" {
48: 		if workflowRunID == "" {
49: 			return "", fmt.Errorf("new workflow run identity must be assigned during Task admission")
50: 		}
51: 		plan.Workflow.RunID = workflowRunID
52: 	}
53: 	data, err := plan.Bind(fmt.Sprintf("t%d", sequence)).Encode()
54: 	if err != nil {
55: 		return "", err
56: 	}
57: 	return db.externalizePlanJSON(data)
58: }
