+	inlineInput := strings.Repeat("A", largePlanInputSize)
+	legacyPlan := fmt.Sprintf(`{"inputs":[{"role":"review-round-file","bytes":"%s"},{"role":"review-round-file","bytes":"%s"}]}`, inlineInput, inlineInput)
