112: func (db *DB) writePlanBlob(digest string, data []byte) (string, error) {
113: 	sum := sha256.Sum256(data)
114: 	if hex.EncodeToString(sum[:]) != digest {
115: 		return "", fmt.Errorf("Task plan input digest mismatch")
116: 	}
117: 	relative := filepath.ToSlash(filepath.Join("blobs", "sha256", digest[:2], digest))
118: 	path := filepath.Join(filepath.Dir(db.Path), filepath.FromSlash(relative))
119: 	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
120: 		return "", fmt.Errorf("create Task plan blob directory: %w", err)
121: 	}
122: 	if existing, err := os.ReadFile(path); err == nil {
123: 		if string(existing) != string(data) {
124: 			return "", fmt.Errorf("Task plan blob %s has different content", digest)
125: 		}
126: 		return relative, nil
127: 	} else if !os.IsNotExist(err) {
128: 		return "", err
129: 	}
130: 	temporary, err := os.CreateTemp(filepath.Dir(path), ".blob-*")
131: 	if err != nil {
132: 		return "", err
133: 	}
134: 	temporaryPath := temporary.Name()
135: 	defer os.Remove(temporaryPath)
136: 	if err := temporary.Chmod(0o600); err != nil {
137: 		_ = temporary.Close()
138: 		return "", err
139: 	}
140: 	if _, err := temporary.Write(data); err != nil {
141: 		_ = temporary.Close()
142: 		return "", err
143: 	}
144: 	if err := temporary.Sync(); err != nil {
145: 		_ = temporary.Close()
146: 		return "", err
147: 	}
148: 	if err := temporary.Close(); err != nil {
149: 		return "", err
150: 	}
151: 	if err := os.Link(temporaryPath, path); err != nil && !os.IsExist(err) {
152: 		return "", err
153: 	}
154: 	if err := syncDirectory(filepath.Dir(path)); err != nil {
155: 		return "", err
156: 	}
157: 	return relative, nil
158: }
