852: func (p Plan) WithoutDependency(taskID, milestone string) (Plan, error) {
853: 	if err := p.Validate(); err != nil {
854: 		return Plan{}, err
855: 	}
856: 	dependencies := make([]dispatch.Dependency, 0, len(p.Dependencies))
857: 	removed := false
858: 	for _, dependency := range p.Dependencies {
859: 		if dependency.TaskID == taskID && dependency.Milestone == milestone {
860: 			removed = true
861: 			continue
862: 		}
863: 		dependencies = append(dependencies, dependency)
864: 	}
865: 	if !removed {
866: 		return Plan{}, fmt.Errorf("prerequisite %s:%s is not in the admitted plan", taskID, milestone)
867: 	}
