869: 	p.AdmittedSHA256 = ""
870: 	p.legacyJSON = ""
871: 	p.Revision++
872: 	p.Dependencies = dependencies
873: 	data, err := p.Encode()
874: 	if err != nil {
875: 		return Plan{}, err
876: 	}
877: 	return Decode(data)
