+func TestLiveTasksDoesNotLoadLargePlanInputs(t *testing.T) {
+	const largePlanInputSize = 65 << 10
+	ctx := context.Background()
+	conn, err := sql.Open("sqlite", ":memory:")
+	if err != nil {
+		t.Fatal(err)
+	}
+	conn.SetMaxOpenConns(1)
