259: func (db *DB) loadAdmittedPlan(taskID int64, data string, revisions ...int) (*taskplan.Plan, error) {
260: 	revision := 0
261: 	if len(revisions) > 0 {
262: 		revision = revisions[0]
263: 	}
264: 	if revision < 1 {
265: 		revision = storedPlanRevision(data)
266: 	}
267: 	if data == "" && revision < 1 {
268: 		if err := db.QueryRow(`SELECT revision,plan_json FROM task_plan_revisions WHERE task_id=? ORDER BY revision DESC LIMIT 1`, taskID).Scan(&revision, &data); err != nil {
269: 			if err == sql.ErrNoRows {
270: 				return nil, nil
271: 			}
272: 			return nil, fmt.Errorf("load latest Task plan revision: %w", err)
273: 		}
274: 	}
275: 	key := taskPlanCacheKey{taskID: taskID, revision: revision}
276: 	if data == "" {
277: 		db.planCacheMu.Lock()
278: 		if cached := db.planCache[key]; cached.plan != nil {
279: 			db.planCacheMu.Unlock()
280: 			return clonePlan(cached.plan), nil
281: 		}
282: 		db.planCacheMu.Unlock()
283: 		if err := db.QueryRow(`SELECT plan_json FROM task_plan_revisions WHERE task_id=? AND revision=?`, taskID, revision).Scan(&data); err != nil {
284: 			if err == sql.ErrNoRows {
285: 				return nil, nil
286: 			}
287: 			return nil, fmt.Errorf("load Task plan revision %d: %w", revision, err)
288: 		}
289: 	}
290: 	jsonDigest := sha256.Sum256([]byte(data))
291: 	db.planCacheMu.Lock()
292: 	if cached := db.planCache[key]; cached.plan != nil && cached.jsonDigest == jsonDigest {
293: 		db.planCacheMu.Unlock()
294: 		return clonePlan(cached.plan), nil
295: 	}
296: 	db.planCacheMu.Unlock()
297: 	var stored taskplan.Plan
298: 	if err := json.Unmarshal([]byte(data), &stored); err != nil {
299: 		return nil, fmt.Errorf("decode execution plan: %w", err)
300: 	}
301: 	admittedDigest := stored.AdmittedSHA256
302: 	stored.AdmittedSHA256 = ""
303: 	for i := range stored.Inputs {
304: 		if stored.Inputs[i].Path == "" {
305: 			continue
306: 		}
307: 		inputBytes, err := db.readPlanBlob(stored.Inputs[i])
308: 		if err != nil {
309: 			return nil, err
310: 		}
311: 		stored.Inputs[i].Bytes = inputBytes
312: 		stored.Inputs[i].Path = ""
313: 	}
314: 	hydratedJSON, err := json.Marshal(stored)
315: 	if err != nil {
316: 		return nil, err
317: 	}
318: 	plan, err := taskplan.Decode(string(hydratedJSON))
319: 	if err != nil {
320: 		return nil, err
321: 	}
322: 	if admittedDigest != "" && plan.Version == taskplan.Version && plan.SHA256() != admittedDigest {
323: 		return nil, fmt.Errorf("Task plan digest does not match its admitted digest")
324: 	}
325: 	plan.AdmittedSHA256 = admittedDigest
326: 	db.planCacheMu.Lock()
327: 	if cached := db.planCache[key]; cached.plan != nil && cached.jsonDigest == jsonDigest {
328: 		plan = *cached.plan
329: 	} else {
330: 		db.cacheTaskPlan(key, jsonDigest, &plan)
331: 	}
332: 	db.planCacheMu.Unlock()
333: 	return clonePlan(&plan), nil
334: }
