51: func (db *DB) externalizePlanJSON(data string) (string, error) {
52: 	var stored taskplan.Plan
53: 	if err := json.Unmarshal([]byte(data), &stored); err != nil {
54: 		return "", err
55: 	}
56: 	existingBlobs := make([]bool, len(stored.Inputs))
57: 	hasExistingBlobs := false
58: 	needsExternalization := false
59: 	for i := range stored.Inputs {
60: 		if stored.Inputs[i].Path == "" {
61: 			needsExternalization = needsExternalization || len(stored.Inputs[i].Bytes) > planInputBlobThreshold
62: 			continue
63: 		}
64: 		existingBlobs[i] = true
65: 		hasExistingBlobs = true
66: 		inputBytes, err := db.readPlanBlob(stored.Inputs[i])
67: 		if err != nil {
68: 			return "", err
69: 		}
70: 		stored.Inputs[i].Bytes = inputBytes
71: 		stored.Inputs[i].Path = ""
72: 	}
73: 	var plan taskplan.Plan
74: 	var err error
75: 	if hasExistingBlobs {
76: 		hydratedJSON, marshalErr := json.Marshal(stored)
77: 		if marshalErr != nil {
78: 			return "", marshalErr
79: 		}
80: 		plan, err = taskplan.Decode(string(hydratedJSON))
81: 	} else {
82: 		plan, err = taskplan.Decode(data)
83: 	}
84: 	if err != nil {
85: 		return "", err
86: 	}
87: 	if !needsExternalization {
88: 		return data, nil
89: 	}
90: 	plan.AdmittedSHA256 = ""
91: 	digest := plan.SHA256()
92: 	for i := range plan.Inputs {
93: 		input := &plan.Inputs[i]
94: 		if input.Role == "brief" || len(input.Bytes) <= planInputBlobThreshold && !existingBlobs[i] {
95: 			continue
96: 		}
97: 		path, err := db.writePlanBlob(input.SHA256, input.Bytes)
98: 		if err != nil {
99: 			return "", err
100: 		}
101: 		input.Path = path
102: 		input.Bytes = nil
103: 	}
104: 	plan.AdmittedSHA256 = digest
105: 	planInputsJSON, err := json.Marshal(plan)
106: 	if err != nil {
107: 		return "", err
108: 	}
109: 	return string(planInputsJSON), nil
110: }
