180: func clonePlan(plan *taskplan.Plan) *taskplan.Plan {
181: 	copy := *plan
182: 	copy.Inputs = append([]taskplan.Input(nil), plan.Inputs...)
183: 	for i := range copy.Inputs {
184: 		copy.Inputs[i].Bytes = append([]byte(nil), plan.Inputs[i].Bytes...)
185: 	}
186: 	copy.Dependencies = append(copy.Dependencies[:0:0], plan.Dependencies...)
187: 	copy.Grants = append(copy.Grants[:0:0], plan.Grants...)
188: 	copy.Preferences = append(copy.Preferences[:0:0], plan.Preferences...)
189: 	copy.MemberAdmissions = append(copy.MemberAdmissions[:0:0], plan.MemberAdmissions...)
190: 	copy.Execution.Members = append(copy.Execution.Members[:0:0], plan.Execution.Members...)
191: 	for i := range copy.Execution.Members {
192: 		if selected := copy.Execution.Members[i].DeleteBranchOnMerge; selected != nil {
193: 			value := *selected
194: 			copy.Execution.Members[i].DeleteBranchOnMerge = &value
195: 		}
196: 	}
197: 	copy.Execution.Paths = append(copy.Execution.Paths[:0:0], plan.Execution.Paths...)
198: 	copy.Launch.Args = append(copy.Launch.Args[:0:0], plan.Launch.Args...)
199: 	copy.Launch.Profile.Args = append(copy.Launch.Profile.Args[:0:0], plan.Launch.Profile.Args...)
200: 	copy.Pool.Setup = append(copy.Pool.Setup[:0:0], plan.Pool.Setup...)
201: 	if plan.UserChoice != nil {
202: 		choice := *plan.UserChoice
203: 		choice.Fields = append([]string(nil), plan.UserChoice.Fields...)
204: 		copy.UserChoice = &choice
205: 	}
206: 	if plan.ValidationLoops != nil {
207: 		loops := *plan.ValidationLoops
208: 		copy.ValidationLoops = &loops
209: 	}
210: 	if plan.Workflow != nil {
211: 		workflow := *plan.Workflow
212: 		workflow.Profile.Stages = append(workflow.Profile.Stages[:0:0], plan.Workflow.Profile.Stages...)
213: 		copy.Workflow = &workflow
214: 	}
215: 	if plan.DeleteBranchOnMerge != nil {
216: 		value := *plan.DeleteBranchOnMerge
217: 		copy.DeleteBranchOnMerge = &value
218: 	}
219: 	return &copy
220: }
