230: func (db *DB) cacheTaskPlan(key taskPlanCacheKey, digest [32]byte, plan *taskplan.Plan) {
231: 	if db.planCache == nil {
232: 		db.planCache = make(map[taskPlanCacheKey]cachedTaskPlan)
233: 	}
234: 	size := taskPlanMemorySize(plan)
235: 	for cachedKey, cached := range db.planCache {
236: 		if cachedKey.taskID == key.taskID && cachedKey.revision != key.revision {
237: 			db.planCacheBytes -= cached.size
238: 			delete(db.planCache, cachedKey)
239: 		}
240: 	}
241: 	if cached := db.planCache[key]; cached.plan != nil {
242: 		db.planCacheBytes -= cached.size
243: 		delete(db.planCache, key)
244: 	}
245: 	if size > taskPlanCacheByteLimit {
246: 		return
247: 	}
248: 	for db.planCacheBytes+size > taskPlanCacheByteLimit {
249: 		for cachedKey, cached := range db.planCache {
250: 			db.planCacheBytes -= cached.size
251: 			delete(db.planCache, cachedKey)
252: 			break
253: 		}
254: 	}
255: 	db.planCache[key] = cachedTaskPlan{jsonDigest: digest, plan: plan, size: size}
256: 	db.planCacheBytes += size
257: }
