121: func (db *DB) migrateTaskPlanRevisionRowsBatch(ctx context.Context, taskCursor int64, revisionCursor int) error {
122: 	rows, err := db.QueryContext(ctx, `SELECT task_id,revision,plan_json FROM task_plan_revisions WHERE task_id>? OR (task_id=? AND revision>?) ORDER BY task_id,revision LIMIT ?`, taskCursor, taskCursor, revisionCursor, planInputMigrationBatchSize)
123: 	if err != nil {
124: 		return err
125: 	}
126: 	type row struct {
127: 		taskID   int64
128: 		revision int
129: 		data     string
130: 	}
131: 	batch := make([]row, 0, planInputMigrationBatchSize)
132: 	for rows.Next() {
133: 		var item row
134: 		if err := rows.Scan(&item.taskID, &item.revision, &item.data); err != nil {
135: 			_ = rows.Close()
136: 			return err
137: 		}
138: 		batch = append(batch, item)
139: 	}
140: 	rowsErr, closeErr := rows.Err(), rows.Close()
141: 	if rowsErr != nil {
142: 		return rowsErr
143: 	}
144: 	if closeErr != nil {
145: 		return closeErr
146: 	}
147: 	type convertedRow struct {
148: 		row
149: 		next string
150: 	}
151: 	converted := make([]convertedRow, 0, len(batch))
152: 	for _, item := range batch {
153: 		next, err := db.externalizePlanJSON(item.data)
154: 		if err != nil {
155: 			return fmt.Errorf("externalize Task %d plan revision %d inputs: %w", item.taskID, item.revision, err)
156: 		}
157: 		converted = append(converted, convertedRow{row: item, next: next})
158: 	}
159: 	tx, err := db.beginTxWithRetry(ctx)
160: 	if err != nil {
161: 		return err
162: 	}
163: 	defer tx.Rollback()
164: 	for _, item := range converted {
165: 		if _, err := tx.ExecContext(ctx, `UPDATE task_plan_revisions SET plan_json=? WHERE task_id=? AND revision=? AND plan_json=?`, item.next, item.taskID, item.revision, item.data); err != nil {
166: 			return err
167: 		}
168: 		taskCursor, revisionCursor = item.taskID, item.revision
169: 	}
170: 	if len(batch) < planInputMigrationBatchSize {
171: 		if _, err := tx.ExecContext(ctx, `UPDATE task_plan_input_migration SET revisions_done=1,revision_task_cursor=?,revision_cursor=? WHERE id=1`, taskCursor, revisionCursor); err != nil {
172: 			return err
173: 		}
174: 	} else if _, err := tx.ExecContext(ctx, `UPDATE task_plan_input_migration SET revision_task_cursor=?,revision_cursor=? WHERE id=1`, taskCursor, revisionCursor); err != nil {
175: 		return err
176: 	}
177: 	return tx.Commit()
178: }
