160: func (db *DB) readPlanBlob(input taskplan.Input) ([]byte, error) {
161: 	if input.Path == "" || filepath.IsAbs(input.Path) || filepath.Clean(filepath.FromSlash(input.Path)) != filepath.FromSlash(input.Path) {
162: 		return nil, fmt.Errorf("invalid Task plan input path")
163: 	}
164: 	path := filepath.Join(filepath.Dir(db.Path), filepath.FromSlash(input.Path))
165: 	relative, err := filepath.Rel(filepath.Dir(db.Path), path)
166: 	if err != nil || relative == ".." || strings.HasPrefix(relative, ".."+string(filepath.Separator)) {
167: 		return nil, fmt.Errorf("Task plan input path escapes POSSE_HOME")
168: 	}
169: 	data, err := os.ReadFile(path)
170: 	if err != nil {
171: 		return nil, fmt.Errorf("read Task plan blob %s: %w", input.SHA256, err)
172: 	}
173: 	sum := sha256.Sum256(data)
174: 	if hex.EncodeToString(sum[:]) != input.SHA256 {
175: 		return nil, fmt.Errorf("Task plan blob %s failed digest verification", input.SHA256)
176: 	}
177: 	return data, nil
178: }
