63: func (db *DB) migrateTaskPlanRowsBatch(ctx context.Context, cursor int64) error {
64: 	rows, err := db.QueryContext(ctx, `SELECT id,plan_json FROM tasks WHERE id>? AND plan_json<>'' ORDER BY id LIMIT ?`, cursor, planInputMigrationBatchSize)
65: 	if err != nil {
66: 		return err
67: 	}
68: 	type row struct {
69: 		id   int64
70: 		data string
71: 	}
72: 	batch := make([]row, 0, planInputMigrationBatchSize)
73: 	for rows.Next() {
74: 		var item row
75: 		if err := rows.Scan(&item.id, &item.data); err != nil {
76: 			_ = rows.Close()
77: 			return err
78: 		}
79: 		batch = append(batch, item)
80: 	}
81: 	rowsErr, closeErr := rows.Err(), rows.Close()
82: 	if rowsErr != nil {
83: 		return rowsErr
84: 	}
85: 	if closeErr != nil {
86: 		return closeErr
87: 	}
88: 	type convertedRow struct {
89: 		row
90: 		next string
91: 	}
92: 	converted := make([]convertedRow, 0, len(batch))
93: 	for _, item := range batch {
94: 		next, err := db.externalizePlanJSON(item.data)
95: 		if err != nil {
96: 			return fmt.Errorf("externalize Task %d plan inputs: %w", item.id, err)
97: 		}
98: 		converted = append(converted, convertedRow{row: item, next: next})
99: 	}
