107: 			return err
108: 		}
109: 		cursor = item.id
110: 	}
111: 	if len(batch) < planInputMigrationBatchSize {
112: 		if _, err := tx.ExecContext(ctx, `UPDATE task_plan_input_migration SET tasks_done=1,task_cursor=? WHERE id=1`, cursor); err != nil {
113: 			return err
114: 		}
115: 	} else if _, err := tx.ExecContext(ctx, `UPDATE task_plan_input_migration SET task_cursor=? WHERE id=1`, cursor); err != nil {
116: 		return err
117: 	}
118: 	return tx.Commit()
